# WARNING: DO NOT EDIT THIS FILE DIRECTLY.
# This file is a child copy that shadows or shares code with the Tools repository.
# Canonical changes must be made in the Tools repository under src/shared/python/
# and synchronized back to UpstreamDrift. Direct edits here risk being lost.

"""Drift guard for plot_theme modules synchronized with Tools.
The baseline hashes were captured from the matching files in the sibling
Tools repository and should only change when that upstream source changes.
"""

from __future__ import annotations

import hashlib
from pathlib import Path

import pytest

REPO_ROOT = Path(__file__).resolve().parents[5 if "tests" in __file__ else 4]
TOOLS_BASELINE_HASHES: dict[str, str] = {
    "src/shared/python/plot_theme/__init__.py": "21b96544f5955ae54c300fc27ea8b17a700fd6c26d4a03ecd7dce509dc52171d",
    "src/shared/python/plot_theme/integration.py": "226affa4a93b71ad271efceefd5cd4e0121b5d4cdc2f71918f281b2f87fabcd0",
    "src/shared/python/plot_theme/manager.py": "ab8b81eb2d6c93b087a89179cea23cd765fdc4fe1d1dbb6d231733bf28dccd5c",
    "src/shared/python/plot_theme/tests/__init__.py": "d77c031b2cc9aea47da6166ec05276ce0499fe3169b52c9262545d9477bb495a",
    "src/shared/python/plot_theme/tests/test_plot_theme.py": "30437f5c9a8b1801d70d64eb694b3a497b7fb74396df84b5b3e5ae8f4a01940d",
    "src/shared/python/plot_theme/themes.py": "6454dc7481b9604894cc1f03c68599c99fde1cba43dc65177c7ba15f8fe8dfb3",
}


def _runtime_equivalent_source(relative_path: str) -> bytes:
    """Return the source bytes that should match the Tools runtime baseline."""
    source = (REPO_ROOT / relative_path).read_text(encoding="utf-8")
    return source.encode("utf-8")


@pytest.mark.parametrize(
    ("relative_path", "expected_sha256"),
    sorted(TOOLS_BASELINE_HASHES.items()),
)
def test_plot_theme_modules_match_tools_baseline(
    relative_path: str,
    expected_sha256: str,
) -> None:
    """Verify the selected leaf modules still match the Tools baseline."""
    path = REPO_ROOT / relative_path
    if not path.exists():
        pytest.fail(f"Missing file: {relative_path}")
    actual_sha256 = hashlib.sha256(
        _runtime_equivalent_source(relative_path)
    ).hexdigest()
    assert actual_sha256 == expected_sha256, relative_path
